def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Reciprocate: donate if the recipient has ever donated to us in the past
    for entry in my_history:
        if entry.get('partner') == recipient_id and entry.get('role') == 'recipient':
            if entry.get('partner_donated', False):
                return True
    return False

